<script setup>
import {ref,onMounted} from 'vue';import {useRoute} from 'vue-router';import PageHeader from '../../components/common/PageHeader.vue';import OrderProgress from '../../components/common/OrderProgress.vue';import StatusView from '../../components/common/StatusView.vue';import {getOrder} from '../../api/orders.js'
const route=useRoute(),order=ref(),loading=ref(true);onMounted(async()=>{try{order.value=(await getOrder(route.params.id)).data}finally{loading.value=false}})
</script>
<template><div class="page-shell"><div class="container"><PageHeader title="订单详情" :breadcrumbs="['首页','我的订单','订单详情']"><el-button plain>联系设计师</el-button></PageHeader><StatusView v-if="loading" type="loading"/><div v-else-if="order"><section class="order-overview"><div><span class="eyebrow">订单 {{order.id}}</span><h1>{{order.name}}</h1><p class="muted">创建于 {{order.createdAt}} · 预计交付 {{order.delivery}}</p></div><div><span class="status-dot progress"></span>{{order.stage}}</div></section><section class="progress-panel"><h2>项目进度</h2><OrderProgress :steps="order.progress" :current="order.current"/></section><div class="order-columns"><section><h2>定制配置</h2><dl><dt>预算范围</dt><dd>{{order.budget}}</dd><dt>负责设计师</dt><dd>{{order.designer}}</dd><dt>主要材料</dt><dd>{{order.materials.join('、')}}</dd><dt>交付时间</dt><dd>{{order.delivery}}</dd></dl></section><section><h2>设计方案</h2><img :src="order.image"><router-link :to="`/schemes/${order.id}`" class="scheme-link">查看完整设计方案 →</router-link></section></div><section class="production"><h2>生产与交付记录</h2><el-timeline><el-timeline-item v-for="(step,i) in order.progress" :key="step.label" :timestamp="step.date||step.status" :type="i<=order.current?'primary':'info'" :hollow="i>order.current"><b>{{step.label}}</b><p>{{i<=order.current?'该阶段信息已更新':'等待前序阶段完成后开始'}}</p></el-timeline-item></el-timeline></section></div><StatusView v-else type="error" title="订单不存在"/></div></div></template>
<style scoped>.order-overview{display:flex;align-items:flex-start;justify-content:space-between;padding:28px 32px;background:#fff;border:1px solid var(--c-border)}.order-overview h1{font:500 28px var(--font-display);margin:8px 0}.progress-panel,.production{margin-top:20px;padding:26px 32px;background:#fff;border:1px solid var(--c-border)}.progress-panel h2,.order-columns h2,.production h2{font:500 20px var(--font-display);margin:0 0 18px}.order-columns{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-top:20px}.order-columns>section{padding:26px 32px;background:#fff;border:1px solid var(--c-border)}dl{display:grid;grid-template-columns:100px 1fr;gap:14px;margin:0}dt{color:var(--c-muted)}dd{margin:0}.order-columns img{height:220px}.scheme-link{display:block;color:var(--c-primary);margin-top:14px}.production p{margin:4px 0;color:var(--c-muted)}@media(max-width:700px){.order-overview{gap:18px;flex-direction:column}.order-columns{grid-template-columns:1fr}}</style>
